--[=[
    @interface INZModel
    数据模型接口定义，负责管理数据状态和变更通知
]=]
export type INZModel = {
    --[=[
        创建新的Model实例
        @param moduleScript ModuleScript Model脚本
        @return INZModel
    ]=]
    new: (moduleScript: any) -> INZModel,

    --[=[
        获取模型数据
        @return {[string]: any} 模型数据表
    ]=]
    GetData: (self: INZModel) -> {[string]: any},

    --[=[
        通知数据变更
        @param path string 数据路径
    ]=]
    Notify: (self: INZModel, path: string) -> (),

    --[=[
        设置数据值
        @param path string 数据路径
        @param value any 新值
    ]=]
    Set: (self: INZModel, path: string, value: any) -> (),
}

return {} 